diff --git a/npm-hub/public/mobile-app.js b/npm-hub/public/mobile-app.js
index 1b2f7bf..6e10dad 100644
--- a/npm-hub/public/mobile-app.js
+++ b/npm-hub/public/mobile-app.js
@@ -4410,13 +4410,24 @@ function renderSnapList() {
     const marks = [];
     if (s.stamp === snapData.recommended) marks.push('<span style="color:var(--acc);font-weight:600">⭐ последний, где что-то делали</span>');
     if (!act) marks.push('<span style="color:var(--warn,#e0a642);font-weight:600">⚠ ничего не делали (пусто)</span>');
+    // ─── WORK-SNAPSHOT ROW ─
+    // The row has to say what the snapshot actually carries. It used to fall
+    // through to «только файлы/аудит» for anything it did not recognise, and
+    // big/ (chunks of a downloaded tool), blobs/ and the browser profile are
+    // exactly what a bad snapshot was made of: 31.4 МБ of «files» and nothing
+    // a restore could use. Naming them is what makes an empty snapshot look
+    // empty instead of plausible.
     const what = [];
     if (s.repos.length) what.push('репо: ' + s.repos.map(r => snapEsc(r.rel) + ' (' + r.kind + ', ' + (r.sized ? snapMb(r.bytes) : 'размер неизвестен') + ')').join(' | '));
     if (s.extrasMb > 0) what.push('дифы/новое: ' + s.extrasMb + ' МБ');
     if (s.chats) what.push('чаты opencode: ' + s.chats);
     if (s.settings) what.push('настройки opencode');
     if (s.sessions) what.push('снимки экрана терминалов');
+    if (s.big > 0) what.push('файлы крупнее блоба: ' + snapMb(s.big) + (s.bigCount ? ' (' + s.bigCount + ')' : ''));
+    if (s.blobs > 0) what.push('разбитые блобы: ' + snapMb(s.blobs) + (s.blobCount ? ' (' + s.blobCount + ')' : ''));
+    if (s.browser) what.push('профиль браузера' + (s.browserBytes ? ': ' + snapMb(s.browserBytes) : ''));
     if (!what.length) what.push('только файлы/аудит');
+// ─── END WORK-SNAPSHOT ROW ─
     return `<label class="snap-row ${sel ? 'sel' : ''}" data-stamp="${snapEsc(s.stamp)}" onclick="snapPick('${snapEsc(s.stamp)}')">
       <input type="radio" name="snap" ${sel ? 'checked' : ''}>
       <div style="flex:1;min-width:0">
