+# и такой снимок лучше пустого. Но он всё равно хуже снимка с
+# репозиториями: тот, кто чинит потерю, должен добраться до работы раньше, чем
+# до 32 МБ скачанного бинаря. Ровно этот случай и лежал на ветке 14 октября -
+# четыре снимка с ngrok в big/ и один с репозиторием двумя сутками раньше.
+snapshot_payload_level() {
