+  printf '%s\n' "$listing" | grep -qE '^repos/.*/(repo\.bundle|worktree\.tar\.gz)$' && { printf '2'; return 0; }
+  printf '%s\n' "$listing" | grep -qE '^opencode/chats/[^/]+\.json$' && { printf '2'; return 0; }
+  # manifest.json в settings - это список файлов, а не сами настройки.
+  printf '%s\n' "$listing" | grep '^opencode/settings/' | grep -qvE '/manifest\.json$' && { printf '2'; return 0; }
+  printf '%s\n' "$listing" | grep -qE '^descriptors/.+' && { printf '2'; return 0; }
+  printf '%s\n' "$listing" | grep -qE '^big/[^/]+/meta\.json$' && { printf '1'; return 0; }
+  printf '%s\n' "$listing" | grep -qE '^blobs/[^/]+/part\.[0-9]+$' && { printf '1'; return 0; }
