+  # идёт за этим к более низкому уровню, а в конце к запасному пути.
+  #
+  # Слешок в конце обязателен: без него ls-tree отдаёт имя самого каталога
+  # snapshots, а не список меток (старый запасной путь как раз это и делал -
+  # он молча указывал на snapshots/ и восстанавливал «из корня», то есть
+  # ни из чего).
+  for entry in $(list_branch_dirs snapshots/ | LC_ALL=C sort -r); do
+    stamp="${entry#snapshots/}"
+    printf '%s' "$stamp" | grep -qE '^[0-9]{8}T[0-9]{6}$' || continue
+    level="$(snapshot_payload_level "snapshots/$stamp")"
+    [ "${level:-0}" -ge "$want" ] 2>/dev/null || continue
+    printf '%s' "$stamp"
+    return 0
+  done
+  return 0
